using W=System.Windows;
using C=System.Windows.Controls;
using U=VelvetVoice.UiControls;
namespace CombinedStudio;
internal sealed class TrueStretchPage:C.ScrollViewer {
 readonly StretchGameWindow gameWindow=new();readonly StretchController controller;readonly W.Window owner;readonly bool fixture;
 readonly C.TextBlock current=U.Text("Reading display…",30,U.Accent),original=U.Text(""),status=U.Text("",13,U.Muted),driver=U.Text("Click Refresh to read monitor devices.",13,U.Muted);
 readonly C.TextBox input=new(){Text="1440x1080",MinHeight=42,MinWidth=210,VerticalContentAlignment=W.VerticalAlignment.Center};
 readonly C.WrapPanel presets=new();readonly C.Button restore;readonly System.Windows.Threading.DispatcherTimer timer=new(){Interval=TimeSpan.FromSeconds(2)};
 internal TrueStretchPage(W.Window owner,string testRoot=null){
  this.owner=owner;fixture=testRoot!=null;controller=new StretchController(fixture?new StretchFixtureDisplay():new WindowsStretchDisplay(),Path.Combine(testRoot??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"YAIOpc","TrueStretch"),"settings.json"));
  VerticalScrollBarVisibility=C.ScrollBarVisibility.Auto;HorizontalScrollBarVisibility=C.ScrollBarVisibility.Disabled;
  var page=new C.StackPanel{Margin=new W.Thickness(30,24,30,24),MaxWidth=1000,HorizontalAlignment=W.HorizontalAlignment.Stretch};Content=page;
  page.Children.Add(U.Text("TRUE STRETCH",32));page.Children.Add(U.Text("Display resolution tools for VALORANT",14,U.Muted));
  var display=U.Section("Current display");display.Children.Add(current);display.Children.Add(original);restore=Button("Restore original",()=>{controller.Restore();gameWindow.Restore();});display.Children.Add(restore);page.Children.Add(U.Card(display));
  var resolution=U.Section("Resolution","Choose a registered GPU mode. Switching affects your primary Windows display.");
  var entry=new C.WrapPanel();input.Margin=new W.Thickness(0,0,12,10);W.Automation.AutomationProperties.SetName(input,"Stretch resolution");entry.Children.Add(input);entry.Children.Add(Button("Apply",()=>controller.Apply(StretchResolution.Parse(input.Text))));var applyFit=Button("Apply + fit VALORANT",()=>{var selected=StretchResolution.Parse(input.Text);controller.Apply(selected);gameWindow.Fit();status.Text="Resolution applied and game window fitted. The in-game Windowed → Fullscreen + Fill → Windowed + Fill setup must already be complete for this session.";});applyFit.IsEnabled=!fixture;entry.Children.Add(applyFit);entry.Children.Add(Button("+ Save current",()=>{controller.AddPreset(input.Text);RenderPresets();}));resolution.Children.Add(entry);var fill=new C.CheckBox{Content="Fill entire monitor (stretch horizontally and vertically)",IsChecked=controller.State.FillMonitor,Foreground=U.Ink,Margin=new W.Thickness(0,4,0,12)};fill.Click+=(_,_)=>Run(()=>{controller.State.FillMonitor=fill.IsChecked==true;controller.Save();});resolution.Children.Add(fill);resolution.Children.Add(Button("Fix full-panel scaling now",()=>{controller.State.FillMonitor=true;fill.IsChecked=true;controller.Apply(controller.Current().Resolution);}));var fitGame=Button("Fit VALORANT window",()=>{gameWindow.Fit();status.Text="Game window fitted. If bars remain inside the image, VALORANT is rendering them; switch to Windowed mode and retry.";});fitGame.IsEnabled=!fixture;resolution.Children.Add(fitGame);resolution.Children.Add(Button("Undo game window fit",()=>gameWindow.Restore()));resolution.Children.Add(U.Text("If bars remain, switch VALORANT to Windowed, then click Fit VALORANT window to maximize it without a frame and verify that its client area fills the current display. Undo restores the previous window. Bars drawn inside the game image still depend on VALORANT and GPU settings.",13,U.Muted));resolution.Children.Add(U.Text("Your confirmed no-bars stretch method (October 15, 2026): 1. Select Windowed in VALORANT. 2. Switch to Fullscreen and select Fill; apply and confirm. 3. Switch back to Windowed, keeping Fill; apply and confirm. 4. Apply your stretch resolution here. Fill alone did not preserve true stretch in your test. Apply + fit combines the resolution switch and borderless window fit; it does not operate the game menus. Repeat the setup if VALORANT resets its display state.",13,U.Muted));
  resolution.Children.Add(U.Text("Popular",13,U.Muted));var popular=new C.WrapPanel();foreach(string value in new[]{"1440x1080","1280x1024","1600x1080","1280x1080","1280x960","1154x1080","1080x1080","1776x1332","1665x1332","1332x1332","1066x1332"})popular.Children.Add(Button(value,()=>{input.Text=value;controller.Apply(StretchResolution.Parse(value));}));resolution.Children.Add(popular);resolution.Children.Add(U.Text("Saved presets",13,U.Muted));resolution.Children.Add(presets);page.Children.Add(U.Card(resolution));
  var options=U.Section("Automatic restore","Keep YAIOpc open. Your original mode returns after VALORANT has been detected running and then closes.");var auto=new C.CheckBox{Content="Restore when VALORANT closes",IsChecked=controller.State.AutoRestore,Foreground=U.Ink,Margin=new W.Thickness(0,8,0,8)};auto.Click+=(_,_)=>Run(()=>{controller.State.AutoRestore=auto.IsChecked==true;controller.Save();});options.Children.Add(auto);page.Children.Add(U.Card(options));
  var monitor=U.Section("Monitor driver","Turn off before launching VALORANT. Administrator permission is requested when you click. This affects all Windows monitor devices and may temporarily affect brightness controls.");monitor.Children.Add(driver);var actions=new C.WrapPanel();actions.Children.Add(Button("Refresh driver status",RefreshDriver));
  foreach(bool enabled in new[]{false,true}){var button=Button(enabled?"Turn on":"Turn off",()=>{});button.IsEnabled=!fixture;button.Click+=async (_,_)=>{button.IsEnabled=false;try{await StretchMonitorDriver.SetEnabled(enabled);RefreshDriver();status.Text="Monitor driver updated.";}catch(Exception error){status.Text=error.GetBaseException().Message;}finally{button.IsEnabled=true;}};actions.Children.Add(button);}monitor.Children.Add(actions);page.Children.Add(U.Card(monitor));
  var guide=new C.Expander{Header="Before you switch",Foreground=U.Ink,Margin=new W.Thickness(0,0,0,16),Content=U.Text("1. Register each custom resolution in NVIDIA Control Panel, AMD Software, or Intel Graphics Software.\n2. Set GPU scaling to Full-screen / Full panel.\n3. Your confirmed sequence: Windowed → Fullscreen + Fill → Windowed + Fill. Apply and confirm each in-game change.\n4. Apply your stretch resolution here only after that sequence. Apply + fit also fits the game window.\n5. The game menu sequence is manual; resizing the window does not replace it.\n\nFor black bars, check your GPU scaling settings. To recover a disabled monitor manually: Device Manager → Monitors → Enable device. Turn the monitor driver on when you finish.",13,U.Muted)};page.Children.Add(U.Card(guide));page.Children.Add(status);
  RenderPresets();Refresh();timer.Tick+=(_,_)=>{try{if(controller.ObserveGame(!fixture&&StretchController.GameRunning())){gameWindow.Restore();status.Text="VALORANT closed. Original display restored.";}Refresh();}catch(Exception error){status.Text=error.Message;}};timer.Start();
  owner.Closing+=(_,args)=>{if(!controller.State.Original.HasValue)return;var choice=W.MessageBox.Show(owner,"A stretch session is active. Restore your original display before closing?\n\nYes: restore and close. No: keep this mode (automatic restore stops). Cancel: stay open.","True Stretch",W.MessageBoxButton.YesNoCancel,W.MessageBoxImage.Question);if(choice==W.MessageBoxResult.Cancel){args.Cancel=true;return;}if(choice==W.MessageBoxResult.Yes){try{controller.Restore();}catch(Exception error){args.Cancel=true;W.MessageBox.Show(owner,error.Message,"Restore failed");}}};owner.Closed+=(_,_)=>{timer.Stop();gameWindow.Dispose();};
 }
 C.Button Button(string caption,Action action){var button=new C.Button{Content=caption,MinHeight=42,MinWidth=115,Margin=new W.Thickness(0,0,10,10),Padding=new W.Thickness(14,8,14,8)};button.Click+=(_,_)=>Run(action);return button;}
 void Run(Action action){try{status.Text="Ready.";action();Refresh();}catch(Exception error){status.Text=error.GetBaseException().Message;}}
 void Refresh(){try{var mode=controller.Current();current.Text=$"{mode.Resolution.Width} × {mode.Resolution.Height}";original.Text=controller.State.Original.HasValue?"Original "+controller.State.Original.Value:"Original "+mode.Resolution+" · no active stretch session";restore.IsEnabled=controller.State.Original.HasValue;}catch(Exception error){status.Text=error.Message;}}
 void RefreshDriver(){if(fixture){driver.Text="Fixture monitor · On";return;}var devices=StretchMonitorDriver.Devices();driver.Text=devices.Count==0?"No monitor devices found.":$"{devices.Count} monitor device(s) · {devices.Count(x=>x.Disabled)} off";}
 void RenderPresets(){presets.Children.Clear();foreach(string value in controller.State.Presets.ToArray()){var row=new C.StackPanel{Orientation=C.Orientation.Horizontal};row.Children.Add(Button(value,()=>{input.Text=value;controller.Apply(StretchResolution.Parse(value));}));row.Children.Add(Button("×",()=>{controller.State.Presets.Remove(value);controller.Save();RenderPresets();}));presets.Children.Add(row);}if(presets.Children.Count==0)presets.Children.Add(U.Text("Save a resolution to add it here.",13,U.Muted));}
 internal void Verify(){controller.AddPreset("1280 × 1024");controller.Apply(new(1280,1024));if(controller.Current().Resolution!=new StretchResolution(1280,1024)||controller.State.Original!=new StretchResolution(1920,1080))throw new Exception("Stretch fixture switch failed");if(controller.ObserveGame(false))throw new Exception("Restored before game ran");controller.ObserveGame(true);if(!controller.ObserveGame(false)||controller.State.Original.HasValue)throw new Exception("Game exit restore failed");Refresh();RenderPresets();}
}
internal sealed class StretchFixtureDisplay:IStretchDisplay {
 StretchResolution mode=new(1920,1080);
 public (string Device,StretchResolution Resolution,uint Frequency,uint Bits) Current()=>("fixture",mode,144,32);
 public void Apply(string device,StretchResolution resolution,uint frequency,uint bits){if(device!="fixture")throw new Exception("Wrong display");mode=resolution;}
}
